d.article(21,'Gelato est une famille de sélections associée à Sherbinskis. La marque annonce un croisement Sunset Sherbert × Thin Mint Cookies ; les numéros comme #41 servent à distinguer des sélections de cette famille.',[
('Un nom de famille pour des sélections',['Une sélection est un matériel retenu parmi une descendance pour ses caractères. Plusieurs sélections issues d’une histoire commune peuvent donc partager le nom Gelato tout en portant un numéro différent.','La présentation actuelle de la marque donne une parenté annoncée ; elle n’établit pas à elle seule la date précise du premier croisement ou de chaque diffusion. Cette chronologie historique reste à confirmer dans le dossier.']),
('Lire les deux noms reliés par le signe ×',['Sherbinskis publie Sunset Sherbert × Thin Mint Cookies. Le signe × signifie que les deux matériels sont présentés comme parents d’un croisement. L’ordre écrit ne suffit pas à imposer le même parent maternel à toutes les versions.','Cette annonce porte sur une histoire revendiquée par la marque. Une analyse indépendante de parentage comparerait, elle, de l’ADN provenant de plantes identifiées. Ce ne serait pas le même type de preuve.']),
('Le numéro identifie une sélection',['Bacio Gelato est associée au numéro #41 sur la page de Sherbinskis. Le nombre n’est ni un pourcentage de cannabinoïdes ni une génération F41 : il sert à désigner une sélection.','Pour savoir quel matériel est décrit, le nom complet, le numéro et le détenteur sont donc utiles. Un lot marqué simplement Gelato ne permet pas de choisir automatiquement une de ces sélections.']),
('Séparer parenté, date et composition',['Le nom des parents annoncés, la date d’un événement et la composition chimique d’un lot sont trois informations différentes. La page actuelle soutient l’annonce de parenté ; les dates historiques restent ouvertes, et les teneurs demandent une analyse du produit concerné.'])], 'Que signifie le numéro dans Gelato #41 ?', ['sélection','croisement','parentage','génération','lot'],'Bacio Gelato / #41 est une sélection nommée, pas une teneur de 41 %.','Le numéro #41 permet-il de connaître le pourcentage de THC ?', 'Non : il désigne une sélection ; une teneur se mesure sur un échantillon.')
for s in d.articles[21]['patch']['sections']:s['sourceIds']=['botany-gelato-sherbinskis-2026']
d.article(22,'Les hybrides CBD viennent de plusieurs programmes de sélection. CBD signifie cannabidiol, un cannabinoïde ; ce mot décrit un composé recherché, pas une espèce de plante ni une origine géographique commune.',[
('Plusieurs programmes, pas un ancêtre unique',['Un hybride résulte d’un croisement entre des matériels. Dans les programmes dits CBD, les sélectionneurs cherchent notamment des profils de cannabinoïdes particuliers, c’est-à-dire des compositions chimiques de la plante.','Resin Seeds et CBD Crew décrivent des programmes distincts. La correction publiée par Resin Seeds en novembre 2015 pour Cannatonic constitue un document daté ; la page actuelle CBD Therapy décrit un autre matériel sans fixer sa date précise de lancement.']),
('Un arbre corrigé et un arbre incomplet',['Resin Seeds annonce Reina Madre × NYCD pour Cannatonic, en remplacement de l’ancienne annonce MK-Ultra × G13. Le signe × relie les deux parents revendiqués, et la correction remplace l’ancienne version au lieu d’ajouter un autre couple biologique.','Pour CBD Therapy, CBD Crew revendique une origine dans des matériels récréatifs à THC plutôt que dans des chanvres industriels, mais ne nomme pas les parents précis sur la page étudiée. On peut enseigner cette origine annoncée sans inventer les cases manquantes de l’arbre.']),
('Un nom de semence ne mesure pas la future plante',['Cannatonic, ACDC, Elektra et CBD Therapy ont leurs histoires et versions propres. CBD Crew reconnaît des différences de rapports CBD/THC entre descendants : un rapport compare ici les quantités relatives des deux composés.','Sélectionner une population pour un caractère demande de suivre sa transmission sur plusieurs descendants. Le nom du programme et celui des parents ne donnent donc pas à eux seuls le résultat chimique de chaque plante ou lot obtenu.']),
('Une composition n’est pas une preuve de traitement',['Le correctif Resin Seeds et la présentation CBD Crew servent ici à comprendre les annonces de sélection. Les promesses thérapeutiques d’une page commerciale ne deviennent pas pour autant des résultats d’essais chez l’humain. L’origine annoncée, la composition mesurée et une efficacité clinique sont des questions séparées.'])], 'Pourquoi une semence appelée CBD ne garantit-elle pas la même composition chez chaque descendant ?', ['CBD','cannabinoïde','hybride','profil chimique','rapport CBD/THC','descendant'],'Le correctif Cannatonic change les parents annoncés ; CBD Therapy conserve des parents précis non publiés.', 'CBD désigne-t-il une espèce ou une molécule ?', 'Une molécule, le cannabidiol ; plusieurs programmes de sélection peuvent rechercher des caractères liés à ce composé.')

VARIETY_DIAGRAMS={
13:('Trois branches portant Haze',[('Original Haze','Authentic Genetics annonce trois composantes colombiennes.'),('Super Silver Haze','Green House annonce Skunk, Northern Lights et Haze.'),('Mango Haze','Mr. Nice décrit une branche parallèle avec un père Haze commun.')],'Chaque ligne correspond à la déclaration d’une maison, pas à trois noms interchangeables.'),
14:('Lire les générations dans le récit Skunk #1',[('Premier apport','Croisement annoncé Afghan–Colombian.'),('Apport suivant','Acapulco Gold est ensuite reliée à cette descendance.'),('Sélections ultérieures','Les matériels et versions doivent garder leurs noms propres.')],'Trois composantes ancestrales n’impliquent pas trois parents directs simultanés.'),
15:('Un ancêtre annoncé dans deux descendants',[('Northern Lights historique','Les parents fondateurs restent non établis ici.'),('Mango Haze','Mr. Nice cite NL5 dans son ascendance.'),('Super Silver Haze','Green House cite Northern Lights dans son ascendance.')],'Ces deux annonces de descendants ne révèlent pas les parents de Northern Lights.'),
16:('Trois usages du nom Kush',[('Hindu Kush','Un lieu et une provenance revendiquée par Sensi.'),('OG Kush','Un récit de transmission depuis la Floride ; fondateurs non établis ici.'),('OG Kush CBD','Dinafem annonce OG Kush × Dancehall.')],'Lieu d’origine, transmission d’une plante et croisement décrivent des événements différents.'),
17:('Lire deux annonces sans confondre les lots',[('NYC Diesel / Soma','Mexican Sativa × Afghani.'),('Cannatonic / Resin Seeds','Reina Madre × NYCD, correctif de 2015.'),('Le lien à vérifier','Le nom NYCD seul ne prouve pas l’identité des plantes employées.')],'Un nom partagé relie des récits ; il ne remplace pas le suivi des échantillons.'),
18:('Suivre la parenté annoncée par étapes',[('Blueberry / Dutch Passion','Composantes Afghani, Thai et Oaxacan annoncées.'),('Blue Dream / HSO','Blueberry × Super Silver Haze.'),('Blue Dream CBD / HSO','Blue Dream × California Orange CBD.')],'Les composantes ancestrales et les parents directs ne se lisent pas à la même génération.'),
19:('Deux versions de White Widow',[('Shantibaba','Brazilian Sativa × South Indian hybrid ; sa version devient Black Widow.'),('Trikoma','Widow Bilbo × Widow BCN pour sa propre White Widow.'),('La comparaison manquante','Une identité génétique entre ces matériels n’est pas établie ici.')],'Deux annonces distinctes ne doivent pas être fondues en un seul couple de parents.'),
20:('Une branche connue, des fondateurs encore ouverts',[('Cookies','Plusieurs sélections portent ce nom de famille.'),('Branche Gelato','Sherbinskis cite Thin Mint Cookies × Sunset Sherbert.'),('Question ouverte','Cette annonce ne reconstitue pas les fondateurs de Girl Scout Cookies.')],'Le croisement déclaré pour un descendant ne révèle pas tout l’arbre de ses ancêtres.'),
21:('Parenté et numéro ne donnent pas la même information',[('Parents annoncés','Sunset Sherbert × Thin Mint Cookies selon Sherbinskis.'),('Sélection nommée','Bacio Gelato / #41.'),('Date historique','Le premier croisement reste à dater séparément.')],'Le numéro désigne une sélection, pas un pourcentage ni une génération.'),
22:('Deux programmes de sélection CBD',[('Cannatonic','Resin Seeds corrige l’annonce en Reina Madre × NYCD en 2015.'),('CBD Therapy','CBD Crew ne publie pas ici les parents précis.'),('Descendants','La composition peut varier : elle se mesure sur le matériel obtenu.')],'Rechercher le même composé ne démontre pas un ancêtre unique commun.')}
for i,(title,nodes,caption) in VARIETY_DIAGRAMS.items():d.diagram(i,title,nodes,caption,after='variants' if i in (13,20,21) else 'parents')
